import { useState, useEffect } from 'react'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { toast } from 'sonner'
import { useAuth } from '@/app/providers/AuthProvider'
import { useShellStore } from '@/app/store/shellStore'
import type { AccentPreset } from '@/app/store/shellStore'
import { PageHeader } from '@/features/shell/PageHeader'
import { profilesService } from '@/integrations/supabase/profiles'
import i18n from '@/shared/i18n/i18n'

const LOCALES = [{ code: 'en', label: 'English' }, { code: 'de', label: 'Deutsch' }, { code: 'es', label: 'Español' }]

export function ProfilePage() {
  const { user } = useAuth()
  const { themeMode, setThemeMode, accentPreset, setAccentPreset } = useShellStore()
  const qc = useQueryClient()
  const [displayName, setDisplayName] = useState('')

  const { data: profile } = useQuery({
    queryKey: ['profile', user?.id],
    queryFn: () => profilesService.getProfile(user!.id),
    enabled: !!user,
  })

  useEffect(() => {
    setDisplayName(profile?.displayName ?? user?.displayName ?? '')
  }, [profile, user])

  const saveMut = useMutation({
    mutationFn: () => profilesService.updateProfile(user!.id, { displayName }),
    onSuccess: () => {
      toast.success('Profile updated')
      qc.invalidateQueries({ queryKey: ['profile', user?.id] })
    },
    onError: (e: Error) => toast.error(e.message),
  })

  return (
    <div className="flex flex-col h-full overflow-hidden">
      <PageHeader title="Profile" />
      <div className="flex-1 overflow-y-auto p-6">
        <div className="max-w-2xl mx-auto flex flex-col gap-6">
          <div className="bg-surface rounded-xl border border-border p-6">
            <div className="flex items-center gap-4 mb-6">
              <div className="h-14 w-14 rounded-full bg-accent/20 flex items-center justify-center text-xl font-bold text-accent">
                {(displayName || user?.displayName || 'U').charAt(0).toUpperCase()}
              </div>
              <div>
                <p className="font-semibold">{displayName || user?.displayName}</p>
                <p className="text-sm text-muted-foreground">{user?.email}</p>
              </div>
            </div>
            <div className="flex flex-col gap-4">
              <div>
                <label className="text-sm font-medium block mb-1.5">Display name</label>
                <input value={displayName} onChange={(e) => setDisplayName(e.target.value)} className="w-full rounded-lg border border-border bg-background px-3 py-2 text-sm outline-none focus:border-accent" />
              </div>
              <button onClick={() => saveMut.mutate()} disabled={saveMut.isPending} className="self-start bg-accent text-accent-foreground px-4 py-2 rounded-lg text-sm hover:opacity-90 disabled:opacity-50">
                {saveMut.isPending ? 'Saving…' : 'Save'}
              </button>
            </div>
          </div>

          <div className="bg-surface rounded-xl border border-border p-6">
            <h3 className="font-medium mb-4">Appearance</h3>
            <div className="flex gap-2 mb-4">
              {(['light', 'dark', 'system'] as const).map((mode) => (
                <button key={mode} onClick={() => setThemeMode(mode)}
                  className={`px-3 py-1.5 rounded-lg text-sm border capitalize ${themeMode === mode ? 'border-accent bg-accent/10 text-accent' : 'border-border text-muted-foreground'}`}>
                  {mode}
                </button>
              ))}
            </div>
            <div className="flex gap-2">
              {(['green', 'blue', 'purple', 'orange', 'rose'] as AccentPreset[]).map((preset) => (
                <button key={preset} onClick={() => setAccentPreset(preset)}
                  className={`px-3 py-1.5 rounded-lg text-sm border capitalize ${accentPreset === preset ? 'border-accent bg-accent/10 text-accent' : 'border-border text-muted-foreground'}`}>
                  {preset}
                </button>
              ))}
            </div>
          </div>

          <div className="bg-surface rounded-xl border border-border p-6">
            <h3 className="font-medium mb-4">Language</h3>
            <div className="flex gap-2">
              {LOCALES.map((locale) => (
                <button key={locale.code} onClick={() => { i18n.changeLanguage(locale.code); localStorage.setItem('nox-locale', locale.code) }}
                  className={`px-3 py-1.5 rounded-lg text-sm border ${i18n.language === locale.code ? 'border-accent bg-accent/10 text-accent' : 'border-border text-muted-foreground'}`}>
                  {locale.label}
                </button>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}
